#include <stdio.h>

int main(void)
{
    int a = 17, b = 5;

    printf("%d %d %d %d %d\n", a + b, a - b, a * b, a / b, a % b);
    printf("%d %d %d\n", a > b, a == b, a != b);
    printf("%d %d %d\n", a > 10 && b > 10, a > 10 || b > 10, !(a > 10));

    a += 3;       /* a = a + 3 */
    b *= 2;       /* b = b * 2 */
    printf("%d %d\n", a, b);

    int i = 5;
    int j = i++;  /* j gets 5, then i becomes 6 */
    int k = ++i;  /* i becomes 7, then k gets 7 */
    printf("%d %d %d\n", i, j, k);

    printf("%d\n", 2 + 3 * 4);    /* * binds tighter than +: 14 */
    printf("%d\n", (2 + 3) * 4);  /* parentheses first: 20 */
    return 0;
}

#include <stdio.h>

int main(void)
{
    int score = 73;

    if (score >= 90) {
        printf("A\n");
    } else if (score >= 70) {
        printf("B\n");
    } else if (score >= 50) {
        printf("C\n");
    } else {
        printf("F\n");
    }

    const char *verdict = score >= 50 ? "pass" : "fail";
    printf("%s\n", verdict);
    return 0;
}

#include <stdio.h>

int main(void)
{
    for (int month = 1; month <= 4; month++) {
        printf("month %d: ", month);
        switch (month) {
        case 12:
        case 1:
        case 2:
            printf("winter\n");
            break;
        case 3:
            printf("spring\n");
            break;
        default:
            printf("unknown\n");
            break;
        }
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n = 1;
    while (n < 100) {        /* keep doubling until the limit */
        n *= 2;
    }
    printf("first power of two >= 100: %d\n", n);

    int attempts = 0;
    do {
        attempts++;
    } while (attempts < 3);
    printf("attempts: %d\n", attempts);

    int sum = 0;
    for (int i = 1; i <= 10; i++) {
        sum += i;
    }
    printf("1 + 2 + ... + 10 = %d\n", sum);

    for (int i = 10; i > 0; i -= 3) {
        printf("i = %d\n", i);
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    /* print odd numbers, but stop at the first multiple of 7 */
    for (int i = 1; i < 20; i++) {
        if (i % 2 == 0) {
            continue;        /* skip even numbers */
        }
        if (i % 7 == 0) {
            printf("stopping at %d\n", i);
            break;           /* leave the loop entirely */
        }
        printf("%d\n", i);
    }
    return 0;
}

